import json
from pathlib import Path

root = Path(__file__).parent
def section(title, text, **kw):
    return dict(title=title, paragraphs=text.strip().split('\n\n'), **kw)
def link(href, title):
    return dict(href=href, title=title)
def table(caption, headers, rows):
    return dict(caption=caption, headers=headers, rows=rows)

